function currencyLabel(c) {
  const m = { EUR: 'EUR', SEK: 'SEK', AED: 'AED', DKK: 'DKK' };
  return m[c] || 'EUR';
}

function makeId(idx) {
  return `euro${String(idx + 1).padStart(3, '0')}`;
}

const entries = UNIVERSITIES.map((u, i) => {
  const fee = u.annualFee === 0 ? (u.currency === 'DKK' ? 95000 : u.annualFee) : u.annualFee;
  const feeUSD = toUSD(fee, u.currency);
  const feeINR = toINR(fee, u.currency);
  const livingUSD = toUSD(u.livingCost, u.currency);
  const livingINR = toINR(u.livingCost, u.currency);
  const qs = u.qsRanking ? u.qsRanking : 'undefined';

  return `  {
    id: '${makeId(i)}', name: '${u.name}', shortName: '${u.shortName}',
    slug: '${u.slug}', country: '${u.country}', state: '${u.state}', city: '${u.city}',
    qsRanking: ${qs}, theRanking: undefined, annualTuitionUSD: ${feeUSD}, annualTuitionINR: ${feeINR},
    livingCostUSD: ${livingUSD}, livingCostINR: ${livingINR},
    intakeMonths: ${JSON.stringify(u.intakes)},
    visaApprovalRate: 75, acceptanceRate: ${u.acceptance},
    popularCourses: ${JSON.stringify(u.popularCourses)},
    scholarships: [
      { name: 'Merit Scholarship', amount: 'Up to 25% tuition', eligibility: 'Academic excellence' },
      { name: 'International Student Award', amount: 'Partial funding', eligibility: 'International applicants' },
    ],
    requirements: { ieltsMin: ${u.ieltsMin}, toeflMin: 90, gpaMin: 7.5, backlogs: 2 },
    employmentRate: ${u.employRate}, avgSalaryUSD: ${u.avgSalUSD}, avgSalaryINR: ${u.avgSalUSD * 84},
    establishedYear: ${u.established}, totalStudents: ${u.students}, internationalStudentPercent: ${u.intlPct},
    campusType: 'Urban', popularAmongIndians: true, applicationFeeUSD: 0,
    description: '${u.name} is a leading institution in ${u.country}, offering world-class programs to international students. Popular among Indian students for its strong industry connections, diverse campus, and excellent career outcomes.',
    highlights: ['${u.country} — Quality education destination', 'English-medium programs', 'Work rights post-study', '${u.intlPct}% international students', 'Employment rate: ${u.employRate}%', 'Strong Indian student community'],
    feeHistory: [{ year: 2022, tuitionUSD: ${Math.round(feeUSD * 0.9)} }, { year: 2023, tuitionUSD: ${Math.round(feeUSD * 0.95)} }, { year: 2024, tuitionUSD: ${feeUSD} }, { year: 2025, tuitionUSD: ${Math.round(feeUSD * 1.05)} }, { year: 2026, tuitionUSD: ${Math.round(feeUSD * 1.08)} }],
    rankingHistory: [{ year: 2022, rank: ${qs === 'undefined' ? 999 : Math.max(1, (u.qsRanking || 999) + 15)} }, { year: 2023, rank: ${qs === 'undefined' ? 999 : Math.max(1, (u.qsRanking || 999) + 10)} }, { year: 2024, rank: ${qs === 'undefined' ? 999 : u.qsRanking || 999} }, { year: 2025, rank: ${qs === 'undefined' ? 999 : u.qsRanking || 999} }, { year: 2026, rank: ${qs === 'undefined' ? 999 : u.qsRanking || 999} }],
    topEmployers: ['Amazon', 'Google', 'Deloitte', 'KPMG', 'PwC', 'McKinsey', 'BCG', 'Accenture'],
    countryCode: '${u.countryCode}',
  }`;
});

const tsSnippet = entries.join(',\n');

// Read existing universities.ts, find the closing ]; and insert before it
const uniFile = path.join(__dirname, '..', 'data', 'universities.ts');
let content = fs.readFileSync(uniFile, 'utf8');

// Find the last ]; in the file (closing the universities array)
// Find "];\nexport function" pattern (handles both LF and CRLF)
const marker = '];\nexport function';
let lastBracket = content.lastIndexOf(marker);
if (lastBracket === -1) {
  const marker2 = '];\r\nexport function';
  lastBracket = content.lastIndexOf(marker2);
}
if (lastBracket === -1) {
  // Try finding just the last ];\n
  lastBracket = content.lastIndexOf('\n];\n');
  if (lastBracket === -1) {
    // dump context
    const idx = content.indexOf('export function getUniversity');
    console.error('Marker not found. Chars around export fn:', JSON.stringify(content.substring(idx-10, idx+10)));
    process.exit(1);
  }
  // Insert at the \n]; position
  const before = content.substring(0, lastBracket + 1); // include the \n before ];
  const after = content.substring(lastBracket + 1); // the ];\n...
  const newContent = before + ',' + '\n' + tsSnippet + '\n' + after;
  fs.writeFileSync(uniFile, newContent, 'utf8');
  console.log(`✅ Added ${UNIVERSITIES.length} universities to data/universities.ts`);
  console.log(`File now has ${newContent.split('\n').length} lines`);
  process.exit(0);
}

// Insert new entries before the ];
const before = content.substring(0, lastBracket);
const after = content.substring(lastBracket);
const newContent = before + ',\n' + tsSnippet + '\n' + after;

fs.writeFileSync(uniFile, newContent, 'utf8');
console.log(`✅ Added ${UNIVERSITIES.length} universities to data/universities.ts`);
console.log(`File now has ${newContent.split('\n').length} lines`);
